<script setup>
import { onMounted } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import { useAutopeer } from '../../state/autopeer';
import { api } from '../../api';
const s=useAutopeer(),route=useRoute(),router=useRouter(); onMounted(async()=>{if(!s.currentUser.value)await s.bootstrap();const node=s.nodes.value.find(x=>x.id===route.params.node);if(route.params.asn){let session=s.sessions.value.find(x=>x.node.id===route.params.node&&String(x.peer.asn)===String(route.params.asn));if(!session){try{const peer=s.isAdmin.value?await api.adminPeer(route.params.node,route.params.asn):await api.getPeer(route.params.node,route.params.asn);if(node)session={node,peer}}catch(e){if(e.status!==404)s.error.value=e.message}}if(session)s.activeSession.value=session}})
</script>
<template><section v-if="s.activeSession.value" class="detail-page"><mdui-button variant="text" @click="router.back()">← Back</mdui-button><p class="eyebrow">{{s.activeSession.value.node.id}} · AS{{s.activeSession.value.peer.asn}}</p><h1>{{s.activeSession.value.node.peering?.display_name||s.activeSession.value.node.name}}</h1><section class="detail-grid"><article class="detail-panel"><h2>Peer configuration</h2><dl class="details-grid"><div><dt>Contact</dt><dd>{{s.activeSession.value.peer.description}}</dd></div><div><dt>WireGuard endpoint</dt><dd class="monospace">{{s.activeSession.value.peer.wireguard_endpoint}}</dd></div><div><dt>WireGuard public key</dt><dd class="monospace">{{s.activeSession.value.peer.wireguard_public_key}}</dd></div><div><dt>BGP transport</dt><dd>{{s.activeSession.value.peer.bgp_transport?.mode}}</dd></div></dl></article></section><mdui-button variant="outlined" @click="s.openEdit(s.activeSession.value);router.push({name:s.isAdmin.value?'admin-peer-edit':'peer-edit',params:route.params})">Edit</mdui-button></section><section v-else class="empty-state"><h2>Session not found</h2></section></template>